{
  "name": "N8700系列可编程直流电源",
  "name_en": "N8700 Series Programmable DC Power Supply",
  "manufacturer": "Agilent Technologies",
  "description": "N8700系列是一类可编程直流电源，用于为实验装置、电子模块或测试样品提供稳定的直流电压和电流输出，并支持输出开关、前面板锁定以及电压、电流、功率测量。在实验室和自动化测试中，常用于器件供电、负载测试和系统集成供电。",
  "description_en": "The N8700 series is a programmable DC power supply used to provide stable DC voltage and current to experimental setups, electronic modules, or test samples. It supports output on/off control, front-panel lockout, and measurement of voltage, current, and power. In laboratories and automated test systems, it is commonly used for DUT powering, load testing, and integrated system power delivery.",
  "tag_hints": [
    "programmable DC power supply",
    "bench power",
    "system power supply",
    "voltage and current sourcing",
    "output measurement",
    "remote sense",
    "automated test equipment"
  ],
  "actions": [
    {
      "action_name": "auto-initialize",
      "description": "初始化电源并使其进入可控工作状态。",
      "description_en": "Initialize the power supply and prepare it for controlled operation."
    },
    {
      "action_name": "auto-lock_front_panel",
      "description": "锁定或解锁电源前面板操作。",
      "description_en": "Lock or unlock the power supply front-panel controls."
    },
    {
      "action_name": "auto-measure_current",
      "description": "测量电源当前输出电流。",
      "description_en": "Measure the present output current of the power supply."
    },
    {
      "action_name": "auto-measure_power",
      "description": "测量电源当前输出功率。",
      "description_en": "Measure the present output power of the power supply."
    },
    {
      "action_name": "auto-measure_voltage",
      "description": "测量电源当前输出电压。",
      "description_en": "Measure the present output voltage of the power supply."
    },
    {
      "action_name": "auto-remote_sense",
      "description": "设置或使用远端检测功能（通常通过感测线连接实现）。",
      "description_en": "Set or use remote sensing for the output, typically implemented through sense-wire connections."
    },
    {
      "action_name": "auto-select_channel",
      "description": "选择要控制或测量的输出通道。",
      "description_en": "Select the output channel to control or measure."
    },
    {
      "action_name": "auto-set_current",
      "description": "设置电源的电流设定值。",
      "description_en": "Set the current setpoint of the power supply."
    },
    {
      "action_name": "auto-set_voltage",
      "description": "设置电源的电压设定值。",
      "description_en": "Set the voltage setpoint of the power supply."
    },
    {
      "action_name": "auto-toggle_output",
      "description": "打开或关闭电源输出。",
      "description_en": "Turn the power supply output on or off."
    }
  ]
}

